use tokio::net::{TcpListener, TcpStream};
use tokio::io::{AsyncReadExt, AsyncWriteExt};

// ---- Simple TCP server ----
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Async Network I/O ===");

    // ---- TCP server ----
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    println!("Server listening on port 8080");

    // ---- Accept connections ----
    tokio::spawn(async move {
        handle_connections(listener).await;
    });

    // ---- Simple HTTP request (using reqwest) ----
    // We'll use a simpler approach

    // ---- Client example ----
    // In a real app, you'd use reqwest for HTTP
    // let response = reqwest::get("https://httpbin.org/ip").await?;
    // println!("Response: {}", response.text().await?);

    println!("Server running. Press Ctrl+C to stop.");

    // Keep the server running
    tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;

    Ok(())
}

async fn handle_connections(mut listener: TcpListener) {
    while let Ok((mut stream, addr)) = listener.accept().await {
        println!("Connection from: {}", addr);

        tokio::spawn(async move {
            handle_client(&mut stream).await;
        });
    }
}

async fn handle_client(stream: &mut TcpStream) {
    let mut buffer = [0; 1024];

    match stream.read(&mut buffer).await {
        Ok(n) if n > 0 => {
            let request = String::from_utf8_lossy(&buffer[..n]);
            println!("Received: {}", request);

            // Echo response
            let response = format!("Echo: {}", request);
            let _ = stream.write_all(response.as_bytes()).await;
        }
        _ => {
            println!("Connection closed");
        }
    }
}

// ---- Simple TCP client ----
async fn client_example() -> Result<(), Box<dyn std::error::Error>> {
    let mut stream = TcpStream::connect("127.0.0.1:8080").await?;

    // Send message
    stream.write_all(b"Hello, server!").await?;

    // Read response
    let mut buffer = [0; 1024];
    let n = stream.read(&mut buffer).await?;
    let response = String::from_utf8_lossy(&buffer[..n]);
    println!("Server response: {}", response);

    Ok(())
}

